import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';

test('renderInvoiceText renders a draft invoice with all fields', () => {
  const invoice = {
    status: 'draft',
    customerName: 'Northwind Studio',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Northwind Studio');
  assert.equal(lines[2], '5x Design work (hour) €85.00 = €425.00');
  assert.equal(lines[3], '3x Development (hour) €95.00 = €285.00');
  assert.equal(lines[4], 'VAT: €149.10');
  assert.equal(lines[5], 'Total: €859.10');
});

test('renderInvoiceText renders an issued invoice with number', () => {
  const invoice = {
    number: 'INV-2025-0001',
    status: 'issued',
    customerName: 'Blue Fern Bakery',
    issueDate: '2025-10-07',
    lines: [{ sku: 'STICKER', name: 'Sticker sheet', qty: 100, unitPrice: 50, vatRate: 21, discountPercent: 0 }],
  };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2025-0001');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.equal(lines[2], '100x Sticker sheet €0.50 = €50.00');
  assert.equal(lines[3], 'VAT: €10.50');
  assert.equal(lines[4], 'Total: €60.50');
});

test('renderInvoiceText formats currency correctly with thousands separators', () => {
  const invoice = {
    status: 'draft',
    customerName: 'Large Corp',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 10, unitPrice: 120000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '10x Logo package €1,200.00 = €12,000.00');
  assert.equal(lines[3], 'VAT: €2,520.00');
  assert.equal(lines[4], 'Total: €14,520.00');
});

test('renderInvoiceText handles a single line item', () => {
  const invoice = {
    status: 'draft',
    customerName: 'Smith & Co',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
  };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines.length, 5);
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Smith & Co');
  assert.equal(lines[2], '1x Design work (hour) €85.00 = €85.00');
  assert.equal(lines[3], 'VAT: €17.85');
  assert.equal(lines[4], 'Total: €102.85');
});

test('renderInvoiceText formats small amounts correctly', () => {
  const invoice = {
    status: 'draft',
    customerName: 'Test Customer',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'ICON-SET', name: 'Icon set (24 icons)', qty: 2, unitPrice: 980, vatRate: 21, discountPercent: 0 },
      { sku: 'PHOTO-LIC', name: 'Stock photo licence', qty: 1, unitPrice: 996, vatRate: 21, discountPercent: 0 },
    ],
  };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '2x Icon set (24 icons) €9.80 = €19.60');
  assert.equal(lines[3], '1x Stock photo licence €9.96 = €9.96');
  assert.equal(lines[4], 'VAT: €6.21');
  assert.equal(lines[5], 'Total: €35.77');
});

test('renderInvoiceText omits VAT line when VAT is zero', () => {
  const invoice = {
    status: 'draft',
    customerName: 'Tax Exempt Corp',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 1, unitPrice: 60000, vatRate: 0, discountPercent: 0 },
    ],
  };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Tax Exempt Corp');
  assert.equal(lines[2], '1x Brand workshop (day, VAT exempt) €600.00 = €600.00');
  assert.equal(lines[3], 'Total: €600.00');
  assert.equal(!lines[4] || !lines[4].startsWith('VAT:'), true);
});

