      { sku: 'LOGO-PACK', name: 'Logo package', qty: 9, unitPrice: 120000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '9x Logo package €1,200.00 = €10,800.00');
  assert.equal(lines[3], 'VAT: €2,268.00');
  assert.equal(lines[4], 'Total: €13,068.00');
});

test('renderInvoiceText handles a single line item', () => {
